const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('N8N_WEBHOOK_SECRET is not set');
}

const item = $input.first();
const headers = item.json.headers || {};
const signatureHeader = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'] || '';
const provided = String(signatureHeader).replace(/^sha256=/i, '').trim();

// n8n may expose rawBody; fall back to re-serializing the body field
let rawBody = item.json.rawBody;
if (!rawBody) {
  const body = item.json.body ?? item.json;
  // Prefer the nested body when webhook wraps the payload
  const payload = item.json.body && typeof item.json.body === 'object' ? item.json.body : {
    eventId: item.json.eventId,
    loanId: item.json.loanId,
    status: item.json.status,
    previousStatus: item.json.previousStatus,
    toolName: item.json.toolName,
    recipientEmail: item.json.recipientEmail,
    role: item.json.role,
    occurredAt: item.json.occurredAt,
  };
  rawBody = typeof body === 'string' ? body : JSON.stringify(payload);
}

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(provided, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid HMAC signature');
}

const payload = typeof item.json.body === 'object' && item.json.body
  ? item.json.body
  : item.json;

return [{
  json: {
    eventId: payload.eventId,
    loanId: payload.loanId,
    status: payload.status,
    previousStatus: payload.previousStatus ?? null,
    toolName: payload.toolName,
    recipientEmail: payload.recipientEmail,
    role: payload.role,
    occurredAt: payload.occurredAt,
  },
}];

// @ts-nocheck
const fs = require('fs');
const path = $env.N8N_LOG_FILE || '/home/node/.n8n-logs/notifications.log';
const payload = $input.first().json;
const line = JSON.stringify({
  channel: 'mock',
  kind: 'request_notification',
  at: new Date().toISOString(),
  to: payload.recipientEmail,
  role: payload.role,
  loanId: payload.loanId,
  status: payload.status,
  toolName: payload.toolName,
  eventId: payload.eventId,
}) + '\n';
fs.appendFileSync(path, line);
return [{ json: { ...payload, logged: true, path } }];
